<"'!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="description" content="单文件离线待办清单，支持新增、完成、删除，数据保存在浏览器 localStorage。">
<title>待办清单</title>
<style>
  :root {
    --bg: #f4f6fa;
    --panel: #ffffff;
    --text: #1f2430;
    --muted: #6b7280;
    --line: #e6e8ee;
    --accent: #2f6feb;
    --accent-soft: rgba(47, 111, 235, .12);
    --danger: #d64545;
    --done: #9aa2b1;
    --radius: 14px;
    --shadow: 0 12px 32px rgba(15, 23, 42, .09);
  }

  @media (prefers-color-scheme: dark) {
    :root {
      --bg: #14171d;
      --panel: #1c2029;
      --text: #e8eaee;
      --muted: #98a1b0;
      --line: #2b3038;
      --accent: #6f9bff;
      --accent-soft: rgba(111, 155, 255, .16);
      --danger: #ff7a6b;
      --done: #6b7480;
      --shadow: 0 12px 32px rgba(0, 0, 0, .35);
    }
  }

  * { box-sizing: border-box; }

  body {
    margin: 0;
    padding: 32px 16px 56px;
    background: var(--bg);
    color: var(--text);
    font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Source Han Sans SC", system-ui, -apple-system, "Segoe UI", sans-serif;
    font-size: 15px;
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
  }

  .wrap { max-width: 620px; margin: 0 auto; }

  .card {
    background: var(--panel);
    border: 1px solid var(--line);
    border-radius: var(--radius);
    box-shadow: var(--shadow);
    padding: 24px;
  }

  header h1 {
    margin: 0;
    font-size: 22px;
    letter-spacing: .5px;
  }

  header p {
    margin: 4px 0 20px;
    color: var(--muted);
    font-size: 13px;
  }

  .add-form {
    display: flex;
    gap: 8px;
    margin-bottom: 14px;
  }

  .add-form input {
    flex: 1;
    min-width: 0;
    padding: 11px 13px;
    font: inherit;
    color: var(--text);
    background: var(--bg);
    border: 1px solid var(--line);
    border-radius: 10px;
    outline: none;
    transition: border-color .15s, box-shadow .15s;
  }

  .add-form input::placeholder { color: var(--muted); }

  .add-form input:focus {
    border-color: var(--accent);
    box-shadow: 0 0 0 3px var(--accent-soft);
  }

  button {
    font: inherit;
    cursor: pointer;
    border: none;
    background: none;
    color: inherit;
  }

  .btn-primary {
    padding: 11px 18px;
    background: var(--accent);
    color: #fff;
    border-radius: 10px;
    font-weight: 600;
    white-space: nowrap;
    transition: filter .15s, opacity .15s;
  }

  .btn-primary:hover { filter: brightness(1.08); }
  .btn-primary:active { filter: brightness(.95); }

  .toolbar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 10px;
    padding-bottom: 14px;
    border-bottom: 1px solid var(--line);
  }

  .filters { display: flex; gap: 4px; }

  .filter-btn {
    padding: 6px 12px;
    border-radius: 999px;
    color: var(--muted);
    font-size: 13px;
    transition: background .15s, color .15s;
  }

  .filter-btn:hover { background: var(--accent-soft); color: var(--accent); }

  .filter-btn.is-active {
    background: var(--accent);
    color: #fff;
  }

  .stats {
    margin-left: auto;
    color: var(--muted);
    font-size: 12.5px;
  }

  .stats b { color: var(--text); font-weight: 600; }

  .list { list-style: none; margin: 0; padding: 0; }

  .task {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    padding: 12px 4px;
    border-bottom: 1px solid var(--line);
    animation: pop .18s ease-out;
  }

  .task:last-child { border-bottom: none; }

  @keyframes pop {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: none; }
  }

  .task__check {
    flex: none;
    width: 22px;
    height: 22px;
    margin-top: 1px;
    border: 2px solid var(--line);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: transparent;
    transition: border-color .15s, background .15s, color .15s;
  }

  .task__check:hover { border-color: var(--accent); }

  .task.is-done .task__check {
    background: var(--accent);
    border-color: var(--accent);
    color: #fff;
  }

  .task__text {
    flex: 1;
    min-width: 0;
    word-break: break-word;
    overflow-wrap: anywhere;
  }

  .task.is-done .task__text {
    color: var(--done);
    text-decoration: line-through;
  }

  .task__meta {
    display: block;
    color: var(--muted);
    font-size: 12px;
    text-decoration: none;
  }

  .task__delete {
    flex: none;
    padding: 4px;
    border-radius: 8px;
    color: var(--muted);
    opacity: .6;
    transition: opacity .15s, color .15s, background .15s;
  }

  .task__delete:hover {
    opacity: 1;
    color: var(--danger);
    background: rgba(214, 69, 69, .12);
  }

  .empty {
    padding: 40px 10px;
    text-align: center;
    color: var(--muted);
  }

  .empty__icon { font-size: 34px; line-height: 1; }
  .empty__title { margin: 10px 0 2px; color: var(--text); font-weight: 600; }
  .empty__hint { font-size: 13px; }

  .footer {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-top: 18px;
    padding-top: 14px;
    border-top: 1px solid var(--line);
    color: var(--muted);
    font-size: 12.5px;
  }

  .link-btn {
    margin-left: auto;
    color: var(--muted);
    text-decoration: underline;
    text-underline-offset: 3px;
    font-size: 12.5px;
  }

  .link-btn:hover { color: var(--danger); }
  .link-btn:disabled { opacity: .4; cursor: not-allowed; text-decoration: none; }
  .link-btn:disabled:hover { color: var(--muted); }

  .notice {
    margin-bottom: 14px;
    padding: 10px 12px;
    border: 1px solid var(--danger);
    border-radius: 10px;
    color: var(--danger);
    font-size: 13px;
  }

  .notice[hidden] { display: none; }

  .toast {
    position: fixed;
    left: 50%;
    bottom: 26px;
    transform: translateX(-50%);
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 16px;
