    const parts = inner.split('=');
    const key = parts[0].replace(/^data-/, '').replace(/-([a-z])/g, (_, c) => c.toUpperCase());
    if (parts.length === 1) {
      if (!(key in node.dataset)) return false;
    } else {
      const want = parts[1].replace(/^['"]|['"]$/g, '');
      if (node.dataset[key] !== want) return false;
    }
  }
  return true;
}

let currentDoc = null;

class FakeElement {
  constructor(tag) {
    this.tagName = String(tag).toUpperCase();
    this.childNodes = [];
    this.parentElement = null;
    this.dataset = {};
    this.attributes = {};
    this._classes = new Set();
    this._text = '';
    this._html = '';
    this.hidden = false;
    this.disabled = false;
    this.value = '';
    this.style = {};
    this._listeners = {};
  }
  get classList() {
    const self = this;
    return {
      add(...c) { c.forEach((x) => self._classes.add(x)); },
      remove(...c) { c.forEach((x) => self._classes.delete(x)); },
      contains(c) { return self._classes.has(c); },
      toggle(c, force) {
        const want = force === undefined ? !self._classes.has(c) : !!force;
        if (want) self._classes.add(c); else self._classes.delete(c);
        return want;
      }
    };
  }
  set className(v) { this._classes = new Set(String(v).split(/\s+/).filter(Boolean)); }
  get className() { return Array.from(this._classes).join(' '); }
  set textContent(v) { this._text = v == null ? '' : String(v); }
  get textContent() { return this._text; }
  set innerHTML(v) { this._html = String(v); this.childNodes = []; }
  get innerHTML() { return this._html; }
  appendChild(child) { child.parentElement = this; this.childNodes.push(child); return child; }
  setAttribute(k, v) { this.attributes[k] = String(v); }
  getAttribute(k) { return Object.prototype.hasOwnProperty.call(this.attributes, k) ? this.attributes[k] : null; }
  addEventListener(type, fn) { (this._listeners[type] = this._listeners[type] || []).push(fn); }
  dispatch(type, event) {
    const ev = Object.assign({ type, target: this, preventDefault() {}, stopPropagation() {} }, event);
    (this._listeners[type] || []).forEach((fn) => fn(ev));
    return ev;
  }
  focus() { if (currentDoc) currentDoc.activeElement = this; }
  closest(sel) { let node = this; while (node) { if (matchesSelector(node, sel)) return node; node = node.parentElement; } return null; }
  querySelectorAll(sel) {
    const out = [];
    const walk = (n) => n.childNodes.forEach((c) => { if (matchesSelector(c, sel)) out.push(c); walk(c); });
    walk(this);
    return out;
  }
}

const ELEMENT_IDS = ['task-input', 'add-form', 'todo-list', 'filters', 'empty-state', 'empty-hint',
  'stat-total', 'stat-active', 'stat-done', 'stats', 'clear-done', 'storage-notice', 'toast', 'toast-text', 'toast-undo'];

function makeDocument() {
  const registry = new Map();
  ELEMENT_IDS.forEach((id) => {
    const el = new FakeElement(id === 'todo-list' ? 'ul' : id === 'add-form' ? 'form' : 'div');
    el.id = id;
    registry.set(id, el);
  });
  // 筛选按钮（真实页面里写在 HTML 中，这里模拟其存在）
  const filters = registry.get('filters');
  ['all', 'active', 'done'].forEach((f) => {
    const b = new FakeElement('button');
    b.className = 'filter-btn';
    b.dataset.filter = f;
    filters.appendChild(b);
  });
  const doc = {
    readyState: 'complete',
    activeElement: null,
    getElementById: (id) => registry.get(id) || null,
    createElement: (tag) => new FakeElement(tag),
    addEventListener() {}
  };
  currentDoc = doc;
  return doc;
}

function makeStorage(store, failMode) {
  return {
    getItem(k) {
      if (failMode === 'get') throw new Error('storage blocked');

