function boot(store, failMode) {
  const doc = makeDocument();
  const win = {
    localStorage: makeStorage(store, failMode),
    setTimeout, clearTimeout,
    addEventListener() {}
  };
  const ctx = vm.createContext({ document: doc, window: win, console });
  vm.runInContext(scriptSrc, ctx, { filename: 'index.html#script' });
  return { ctx, doc, store };
}

/* ---------- 断言 ---------- */
let pass = 0, fail = 0;
function ok(cond, name, extra) {
  if (cond) { pass++; console.log('  ✅ ' + name); }
  else { fail++; console.log('  ❌ ' + name + (extra ? ' -> ' + extra : '')); }
}
function eq(actual, expected, name) {
  ok(actual === expected, name, '期望 ' + JSON.stringify(expected) + '，实际 ' + JSON.stringify(actual));
}
function section(t) { console.log('\n▶ ' + t); }

